    const body = dataRows.map((row)=>"<tr>".concat(row.map((v, i)=>"<td".concat(i === 1 ? ' class="name-cell"' : "", ">").concat(escapeHtml(v === undefined || v === null || v === "" ? "-" : v), "</td>")).join(""), "</tr>")).join("");
